export function lettersToColNum(letters) {
  letters = letters.toUpperCase()
  if (letters.length === 1) {
    return letters.charCodeAt(0) - 64
  }
  const c1 = letters.charCodeAt(0) - 64
  const c2 = letters.charCodeAt(1) - 64
  return c1 * 26 + c2
}

export function colNumToLetters(num) {
  if (num <= 26) {
    return String.fromCharCode(64 + num)
  }
  const c2 = ((num - 1) % 26) + 1
  const c1 = (num - c2) / 26
  return String.fromCharCode(64 + c1) + String.fromCharCode(64 + c2)
}

// Splits a bare word (letters followed by digits, as produced by the formula
// tokenizer) into its letters and digits parts. Returns null if the word does
// not have that shape (should not happen for tokens produced by our lexer).
export function splitWord(word) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(word)
  if (!m) return null
  return { letters: m[1], digits: m[2] }
}

// Validates a word (letters + optional digits) as a cell address in range.
// Returns { col, row, key, canonical } or null if out of the addressable range.
export function resolveAddressWord(word) {
  const parts = splitWord(word)
  if (!parts) return null
  return resolveAddressParts(parts.letters, parts.digits)
}

export function resolveAddressParts(letters, digits) {
  if (letters.length < 1 || letters.length > 2) return null
  if (digits.length < 1 || digits.length > 3) return null
  const row = parseInt(digits, 10)
  if (!(row >= 1)) return null
  const col = lettersToColNum(letters)
  const canonical = letters.toUpperCase() + String(row)
  const key = canonical
  return { col, row, key, canonical }
}

// Strict validation for a declaration-line address token: must be exactly
// 1-2 letters followed by 1-3 digits naming a row >= 1, nothing else.
export function parseStrictAddress(token) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(token)
  if (!m) return null
  return resolveAddressParts(m[1], m[2])
}

export function compareAddr(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

