{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-L3a1Jl/src/sheet.js","content":"import { parseStrictAddress } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
    this.name = 'SheetError'
  }
}

// Parses the whole sheet text into a Map from canonical address key to
// { content, col, row, canonical }.
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    let idx = -1
    for (let j = 0; j < stripped.length; j++) {
      const ch = stripped[j]
      if (ch === ' ' || ch === '\t') {
        idx = j
        break
      }
    }

    let addressToken, content
    if (idx === -1) {
      addressToken = stripped
      content = ''
    } else {
      addressToken = stripped.slice(0, idx)
      let j = idx
      while (j < stripped.length && (stripped[j] === ' ' || stripped[j] === '\t')) j++
      content = stripped.slice(j)
    }

    const addr = parseStrictAddress(addressToken)
    if (!addr) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${addressToken}`)
    }

    if (cells.has(addr.key)) {
      throw new SheetError(`line ${lineNo}: cell ${addr.canonical} is declared twice`)
    }

    cells.set(addr.key, { content, col: addr.col, row: addr.row, canonical: addr.canonical })
  }

  return cells
}
"}

