    const cell = this.cells.get(key)
    if (!cell) return numLit(0)
    if (!cell.content.startsWith('=')) {
      return evalLiteral(cell.content)
    }
    const ast = this.getAst(key)
    if (!ast) return ERR_ERR
    return this.evalNode(ast)
  }

