    const from = resolveAddressWord(node.from)
    const to = resolveAddressWord(node.to)
    if (!from || !to) return [ERR_REF]
    const minCol = Math.min(from.col, to.col)
    const maxCol = Math.max(from.col, to.col)
    const minRow = Math.min(from.row, to.row)
    const maxRow = Math.max(from.row, to.row)
    const values = []
    for (let col = minCol; col <= maxCol; col++) {
      const letters = colNumToLetters(col)
      for (let row = minRow; row <= maxRow; row++) {
        const key = letters + String(row)
        values.push(this.getValue(key))
      }
    }
    return values
  }

  // Used for arguments that a function reduces to a single value (ABS's
  // sole argument, IF's condition and taken branch): if the argument is a
  // range, use its first covered value (after letting range expansion run,
  // so errors and evaluation side effects within the range still happen).
