// Structurally collects every distinct in-range address named directly by a
// (grammar-accepted) formula AST, ranges expanded, ordered by column then
// row. Does not evaluate anything, so both branches of IF are included.
export function collectDeps(ast) {
  const found = new Map() // key -> {col,row}

  function addAddress(raw) {
    const addr = resolveAddressWord(raw)
    if (addr) found.set(addr.key, { col: addr.col, row: addr.row })
  }

  function addRange(node) {
    const from = resolveAddressWord(node.from)
    const to = resolveAddressWord(node.to)
    if (!from || !to) return
    const minCol = Math.min(from.col, to.col)
    const maxCol = Math.max(from.col, to.col)
    const minRow = Math.min(from.row, to.row)
    const maxRow = Math.max(from.row, to.row)
    for (let col = minCol; col <= maxCol; col++) {
      for (let row = minRow; row <= maxRow; row++) {
        const key = colNumToLetters(col) + String(row)
        found.set(key, { col, row })
      }
    }
  }

  function walk(node) {
    switch (node.kind) {
      case 'number':
      case 'bool':
        return
      case 'address':
        addAddress(node.raw)
        return
      case 'unary':
        walk(node.operand)
        return
      case 'binop':
        walk(node.left)
        walk(node.right)
        return
      case 'call':
        for (const arg of node.args) {
          if (arg.kind === 'range') addRange(arg)
          else walk(arg)
        }
        return
      default:
        throw new Error(`unexpected node kind ${node.kind}`)
    }
  }

  walk(ast)

  const list = [...found.entries()].map(([key, pos]) => ({ key, ...pos }))
  list.sort(compareAddr)
  return list.map((e) => colNumToLetters(e.col) + String(e.row))
}
"}

