  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const sortedKeys = [...cells.entries()]
    .map(([key, cell]) => ({ key, col: cell.col, row: cell.row }))
    .sort(compareAddr)
    .map((e) => e.key)

  const out = []

  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const key of sortedKeys) {
      const cell = cells.get(key)
      const value = evaluator.getValue(key)
      out.push(`${cell.canonical}=${formatValue(value)}`)
    }
  } else {
    const evaluator = new Evaluator(cells)
    for (const key of sortedKeys) {
      const cell = cells.get(key)
      let depsList = []
      if (cell.content.startsWith('=')) {
        const ast = evaluator.getAst(key)
        if (ast) depsList = collectDeps(ast)
      }
      const parts = [`${cell.canonical}:`, ...depsList]
      out.push(parts.join(' '))
    }
  }

  process.stdout.write(out.length > 0 ? out.join('\n') + '\n' : '')
  process.exit(0)
}

function readStdinSync() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

main()
