import { collectDeps } from './deps.js'
import { formatNumber } from './format.js'
import { compareAddr } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function formatValue(v) {
  switch (v.type) {
    case 'number':
      return formatNumber(v.value)
    case 'error':
      return v.value
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'text':
      return v.value
    default:
      throw new Error(`unexpected value type ${v.type}`)
  }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
    }
    throw e
  }

  const sortedKeys = [...cells.entries()]
    .map(([key, cell]) => ({ key, col: cell.col, row: cell.row }))
    .sort(compareAddr)
    .map((e) => e.key)

  const out = []
  const evaluator = new Evaluator(cells)

  if (mode === 'values') {
    for (const key of sortedKeys) {
      const cell = cells.get(key)
      const value = evaluator.getValue(key)
      out.push(`${cell.canonical}=${formatValue(value)}`)
    }
  } else {
    for (const key of sortedKeys) {
      const cell = cells.get(key)
      let depsList = []
      if (cell.content.startsWith('=')) {
        const ast = evaluator.getAst(key)
        if (ast) depsList = collectDeps(ast)
      }
      const parts = [`${cell.canonical}:`, ...depsList]
      out.push(parts.join(' '))
    }
  }

  process.stdout.write(out.length > 0 ? out.join('\n') + '\n' : '')
  process.exit(0)
}

main()

