export function roundSignificant(num, sig = 10) {
  if (num === 0) return 0
  if (!Number.isFinite(num)) return num
  const sign = num < 0 ? -1 : 1
  const abs = Math.abs(num)
  const d = Math.floor(Math.log10(abs)) + 1
  const power = sig - d
  const magnitude = Math.pow(10, power)
  let shifted = Math.round(abs * magnitude)
  // Rounding may bump the digit count (e.g. 9.999999999... -> 10...), which
  // Math.round already accounts for since we just format the resulting
  // integer back out; no special case needed there.
  let result = shifted / magnitude
  return sign * result
}

